// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue } from '@skyramp/skyramp';
import { createUser, getUser, deleteUser } from './skyrampUtils';

// Id of the user this test creates, so cleanup runs even when an assertion fails.
let createdUserId: any = null;

test.afterEach(async () => {
    if (createdUserId === null) return;
    const cleanupClient = new SkyrampClient();
    const usersUsersDeleteResponse = await deleteUser(cleanupClient, createdUserId, "testbotpassword123", 200);
    expect(usersUsersDeleteResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(usersUsersDeleteResponse, "response"), 'response').toBe("User account and all related data deleted successfully.");
    createdUserId = null;
});

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Declaration of variables
    const username = "4242424242";

    const usersPostResponse = await createUser(client, "Numeric Username Probe", username, "probepassword123", 201);
    expect(usersPostResponse.statusCode, 'status code').toBe(201);
    createdUserId = getResponseValue(usersPostResponse, "response.id");
    expect(getResponseValue(usersPostResponse, "response.username"), 'username').toBe("4242424242");
    expect(getResponseValue(usersPostResponse, "response.name"), 'name').toBe("Numeric Username Probe");
    expect(getResponseValue(usersPostResponse, "response.id"), 'id').toBeGreaterThan(0);
    expect(getResponseValue(usersPostResponse, "response.password"), 'password carries no value').toBeNull();

    const usersUsersGetResponse = await getUser(client, username, 200);
    expect(usersUsersGetResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(usersUsersGetResponse, "response.username"), 'username').toBe("4242424242");
    expect(getResponseValue(usersUsersGetResponse, "response.id"), 'id').toBe(getResponseValue(usersPostResponse, "response.id"));
    expect(getResponseValue(usersUsersGetResponse, "response.name"), 'name').toBe("Numeric Username Probe");
});
